// One array per output, sized for the two characters
local chara = [0, 0];
local msg = [0, 0];
local motPath = ["", ""];
local motType = [0, 0];
local extMtnPath = ["", ""];
local extMtnName = ["", ""];
local teamID = [2, 2];
local order = [0, 1];
CMND_BTL_GET_CONVSMSG(chara, msg, motPath, motType, extMtnPath, extMtnName, teamID, order);

// ... create and load the two models from chara[] and teamID[] ...

// First speaker, then the answer if there is one
if (msg[order[0]])
{
	CMND_SET_MOTION(hdlCh[order[0]], extMtnName[order[0]]);
	CreateSpeech(msg[order[0]], chara[order[0]], order[0]);

	if (msg[order[1]])
	{
		CMND_SET_MOTION(hdlCh[order[1]], extMtnName[order[1]]);
		CreateSpeech(msg[order[1]], chara[order[1]], order[1]);
	}
}
